select
  c.issue_key as issueKey,
  c.change_data as changeData,
  coalesce(c.issue_change_creation_date, c.created_at) as changedAt,
  c.user_login as userLogin
from issue_changes c
inner join issues i on i.kee = c.issue_key and i.issue_type <> 4
inner join project_branches pb on pb.uuid = c.project_uuid and pb.is_main = ${_true}
inner join projects p on p.uuid = pb.project_uuid
where
  p.organization_uuid = #{organizationUuid,jdbcType=VARCHAR}
  and c.change_type = 'diff'
  and c.created_at >= #{minCreatedAt,jdbcType=BIGINT}
  and coalesce(c.issue_change_creation_date, c.created_at) >= #{fromDate,jdbcType=BIGINT}
  and coalesce(c.issue_change_creation_date, c.created_at) < #{toDate,jdbcType=BIGINT}
  and c.change_data like '%resolution=%'

mapper.sql:
from issue_changes c
inner join issues i on i.kee = c.issue_key
inner join project_branches pb on pb.uuid = c.project_uuid and pb.is_main = ${_true}
inner join projects p on p.uuid = pb.project_uuid
inner join rules r on r.uuid = i.rule_uuid
left outer join components comp on comp.uuid = i.component_uuid
where
  p.organization_uuid = #{query.organizationUuid,jdbcType=VARCHAR}
  and c.created_at >= #{query.minCreatedAt,jdbcType=BIGINT}
  and coalesce(c.issue_change_creation_date, c.created_at) >= #{query.fromDate,jdbcType=BIGINT}
  and coalesce(c.issue_change_creation_date, c.created_at) < #{query.toDate,jdbcType=BIGINT}
  and (



        (c.change_type = 'diff' and (c.change_data like '%resolution=%' or c.change_data like '%status=%'))


        (c.change_type = 'diff' and c.change_data like '%severity=%')


        c.change_type = 'comment'


        c.change_type = 'exception_reason'



  )

    and c.user_login is not null


    and c.user_login = #{query.userUuid,jdbcType=VARCHAR}


    and p.uuid = #{query.projectUuid,jdbcType=VARCHAR}
